const CLUB_MAP = new Map<string, ClubInfo>(CLUB_DATA.map((c) => [c.id, c]));

export function getClub(id?: string | null): ClubInfo | undefined {
  if (!id) return undefined;
  return CLUB_MAP.get(id);
}

export default CLUB_DATA;
